import {chapterOfRecord} from './chapter-records.js';
import {CHAPTER_TITLES} from './chapter-names.js';
// The fields of every record editor of the eleven chapters, described once (audit F2-11; round 11, the field kit). A
// descriptor names the field as the command payload names it, its label, its kind (text, textarea, select, checkbox,
// number, date, url; 'ids' for a list of linked record ids chosen by checkboxes; 'perItem' for one field per chosen
// item, named prefix + id), whether it is required and its limits, so a field-level assistant can key on
// {command, name}. One renderer (fieldHTML, through recordField) draws every field of every editor from these
// descriptors: label, help (fieldHelp), the required marker, maxlength, type, options and the inline error slot the
// dialog primitive fills (dialog.js fieldMessage). The studio dialog browser gate holds every editor it opens to the
// descriptors of its record type (formFieldsMatch), so the vocabulary cannot drift unseen. Vocabulary is shared
// across chapters: `title` (never name/label), `purpose` (never description/summary), `owner`, `rationale`,
// `source`, `evidence`, `assumptions`, `status`. Each record type has its own form id (FORM_IDS).
//
// The Chapter 1–3 page apps (requirements.js, quality.js, decisions.js) are described here too (round 2, I2-12), so
// that the field spark and the server's provenance check key on them the same way. Their descriptors follow what
// those forms send and those records store, which predates the shared vocabulary (an artefact's `description`, an
// alternative's `summary`, a conflict's `effect`); they are listed in PAGE_RECORD_TYPES and left out of
// vocabulary(), which is the studios' rule. The evidence, review and walkthrough forms of Chapters 7–11 and the
// process editor's forms (EVIDENCE_RECORD_TYPES) carry the names their commands have always taken (a reviewer's
// `notes`, a review `outcome`) and are left out of vocabulary() the same way. A record type is the command that
// saves it ('artefact' saves every Chapter 1 artefact type, told apart by its `type`; 'decision.alternative' saves an
// alternative nested in a decision). A free-text field that is part of a measured target (a driver's metric, unit
// and window) is marked `measure`: it gets no spark and no draft, like the target value itself.
//
// Limits: a descriptor's maxlength is the domain's limit for that field (the domain stays the authority; the browser
// limit is a convenience that agrees with it). The common limits are 160 for a title, 180 for a name of a person,
// 4000 for prose unless the domain keeps less (2400 in Chapters 8–10, 1000 in the process editor).
//
// Pickers (round 11): a field with `picker` offers the linked records of the project as a datalist (owner: the
// stakeholders of Chapter 1, free text kept for people not recorded) or as the choices of an ids field (assumption:
// Chapter 1's assumption records). Pattern, anti-pattern and tactic pickers are filled from the knowledge catalogue
// and the playbook once the editor is on screen (fillPickers), so no chapter loads the catalogue to open an editor.
import {esc,shortText} from './html-escape.js';
import {requirementSearchIndex,requirementGroups} from './requirement-groups.js';
// The playbook's tactics are in every chapter already (the decision and quality domains read them); the catalogue is
// loaded only when a pattern field is on screen.
import {TACTICS} from './playbook-knowledge.js';
// The execution agreement's fields (data only: the manifest loads no evaluator).
import {EXECUTION_FIELDS} from './composition-manifest.js';
const T=(name,label,extra={})=>({name,label,kind:'text',...extra});
const A=(name,label,extra={})=>({name,label,kind:'textarea',...extra});
const S=(name,label,options,extra={})=>({name,label,kind:'select',options,...extra});
const C=(name,label,extra={})=>({name,label,kind:'checkbox',...extra});
const N=(name,label,extra={})=>({name,label,kind:'number',...extra});
const D=(name,label,extra={})=>({name,label,kind:'date',...extra});
// A list of linked record ids, chosen with one checkbox per record (FormData.getAll(name)).
const I=(name,label,extra={})=>({name,label,kind:'ids',...extra});
// One field per chosen item, named prefix + item id (e.g. `scope:tc-001`), next to the item it qualifies.
const P=(name,label,control,extra={})=>({name,label,kind:'perItem',prefix:name+':',control,...extra});
// A field that only the proposal ("ghost") review form carries, not the ordinary editor.
const proposal={proposalOnly:true};
// One field per row of a repeated group, named prefix + row number (an alternative's `rel-label-0`).
const Row=(name,label,control,extra={})=>({name,label,kind:'perItem',prefix:name+'-',control,...extra});
// Part of a measured target: free text, but no spark and no draft (a number's metric, unit and window); round 12 marks
// so the values a person records as they stand: an outcome's figures, a rule's value, an imported attribute, a journey.
const measure={measure:true};
// A field the form carries for itself and the record does not keep (a ghost's proposed relationship): no spark.
const form={form:true};
const req={required:true};
// The accountable person of a record: free text, 180 characters, with the stakeholders of Chapter 1 offered.
const owner=(label='Accountable owner',extra={})=>T('owner',label,{maxlength:180,picker:'stakeholder',...extra});
const person=(name,label,extra={})=>T(name,label,{maxlength:180,picker:'stakeholder',...extra});
