// Round 12 (DM-02, DM-03): the requirements and requirement groups a record answers itself, typed as their ids; the form
// sends them as requirementIds and requirementGroupIds.
const grounds=(extra={})=>T('grounds','Requirements and groups it answers',{maxlength:60000,placeholder:'REQ-001, RG-001',...form,...extra});
// The typed ids, read back: requirement groups are RG-nnn, every other id a requirement (the domain refuses unknown ids
// by name). The words of a record's links, for the field.
export const groundsOf=v=>{const ids=[...new Set(String(v||'').split(/[\s,;]+/).filter(Boolean))];return {requirementIds:ids.filter(id=>!/^RG-\d+$/.test(id)),requirementGroupIds:ids.filter(id=>/^RG-\d+$/.test(id))};};
export const groundText=r=>[...(Array.isArray(r?.requirementIds)?r.requirementIds:[]),...(Array.isArray(r?.requirementGroupIds)?r.requirementGroupIds:[])].join(', ');
// rc41 close: the execution agreement of an interface contract (Chapter 8's contract editor posts it as execution.<key>;
// interfaces-ui.js formValues folds it into the record's `execution`). The contract that defines it is the bounded
// interpretation in composition-manifest.js (EXECUTION_FIELDS, the owner's rc38 snapshot): each descriptor takes its
// label, its choices and its limits from there, so the editor, the reading and this vocabulary cannot drift apart. A
// reference (an environment, a part, another contract, an accepted read design) is a choice the editor fills from the
// project. These are declarations a person states as they stand, never inferred (the manifest): no spark and no draft.
const EXECUTION_DESCRIPTORS=EXECUTION_FIELDS.map(f=>{
 const name='execution.'+f.key,base={execution:true,...measure};
 if(f.type==='number')return N(name,f.label,{min:f.min,max:f.max,step:f.integer?'1':'any',...base});
 if(f.type==='field')return T(name,f.label,{maxlength:100,...base});
 return S(name,f.label,f.options||[],base);
});
