export const fieldHelp=(command,name)=>FIELD_HELP[command]?.[name]||FIELD_HELP['*'][name]||'';
// Compares the named controls of a rendered form with the descriptors of its record type: what the form has
// that no descriptor names (`undescribed`), and what a descriptor names that the form lacks (`missing`;
// proposal-only fields may be absent from the ordinary editor). Both empty = the form speaks the vocabulary.
export function formFieldsMatch(command,names,{proposal:isProposal=false}={}){
 const ds=fieldsFor(command),list=[...new Set(names)];
 const described=n=>ds.some(d=>d.kind==='perItem'?n.startsWith(d.prefix):d.name===n);
 return {undescribed:list.filter(n=>!described(n)),missing:ds.filter(d=>d.kind!=='perItem'&&!(d.proposalOnly&&!isProposal)&&!d.optional&&!list.includes(d.name)).map(d=>d.name)};
}
export const fieldOf=(command,name)=>fieldsFor(command).find(f=>f.name===name)||null;
// Every field name the studios use, with the record types that use it: the shared vocabulary, checkable by a test.
// The Chapter 1–3 page apps and the evidence forms keep the names their stored records use; `pages: true` lists
// theirs as well.
export function vocabulary({pages=false}={}){const v=new Map();for(const [command,fields] of Object.entries(RECORD_FIELDS)){if(!pages&&(PAGE_RECORD_TYPES.has(command)||EVIDENCE_RECORD_TYPES.has(command)))continue;for(const f of fields){if(!v.has(f.name))v.set(f.name,[]);v.get(f.name).push(command);}}return v;}

// ---------------------------------------------------------------- the renderer
let uid=0;
const nextId=prefix=>prefix+'-'+(++uid);
// An option: [id, text], {id, title, note, strong, disabled} or a bare value.
const optionOf=o=>Array.isArray(o)?{id:o[0],title:o[1]}:o&&typeof o==='object'?o:{id:o,title:o};
const optionHTML=(o,current)=>{const x=optionOf(o);return `<option value="${esc(String(x.id??''))}"${String(x.id??'')===String(current??'')?' selected':''}>${esc(String(x.title??x.id??''))}</option>`;};
const checkRowHTML=(name,o,chosen)=>{const x=optionOf(o);return `<label><input type="checkbox" name="${esc(name)}" value="${esc(String(x.id))}"${chosen.includes(String(x.id))?' checked':''}${x.disabled?' disabled':''}><span>${x.strong?`<b>${esc(String(x.strong))}</b> `:''}${esc(String(x.title??''))}${x.note?`<small>${esc(String(x.note))}</small>`:''}</span></label>`;};
// Renders one field from its descriptor. `options` and `value` come from the studio; `label` overrides the caption
// (a per-item field names its item); `item` renders a perItem descriptor for that item; `help` is the sentence under
// the field; `extra` attributes are appended as given; `empty` is the sentence an ids field shows with nothing to
// choose. A text field with options offers them as a datalist and keeps free text.
export function fieldHTML(d,value='',opts={}){
 if(!d)return '';
 const {className='l-field',options=d.options||[],extra='',help=d.help||'',label=d.label,item=null,required=d.required,rows=d.rows,empty='',list=null}=opts;
 const name=item!=null?d.prefix+item:d.name,kind=item!=null?(d.control||'text'):d.kind;
 const helpId=help?nextId('field-help'):'',helpHTML=help?`<small class="field-help" id="${helpId}">${esc(help)}</small>`:'';
 const attrs=` name="${esc(name)}"${required?' required aria-required="true"':''}${d.maxlength?` maxlength="${d.maxlength}"`:''}${d.min!=null?` min="${d.min}"`:''}${d.max!=null?` max="${d.max}"`:''}${d.step?` step="${d.step}"`:''}${d.placeholder?` placeholder="${esc(d.placeholder)}"`:''}${helpId?` aria-describedby="${helpId}"`:''}${extra?' '+extra:''}`;
 const caption=`<span>${esc(label)}</span>`;
 // An ids field with nothing to choose yet still carries its name, on a disabled input FormData leaves out.
 if(kind==='ids'){const chosen=(Array.isArray(value)?value:[]).map(String);if(opts.grouped||options.length>PICK_FROM)return pickHTML(name,label,helpHTML,options,chosen,false,helpId);return `<fieldset class="l-checks"><legend>${esc(label)}</legend>${helpHTML}${options.map(o=>checkRowHTML(name,o,chosen)).join('')||`<input type="hidden" name="${esc(name)}" value="" disabled>`+(empty?`<p class="l-note">${esc(empty)}</p>`:'')}</fieldset>`;}
 if(kind==='checkbox')return `<label class="l-checkbox"><input type="checkbox"${attrs}${value?' checked':''}>${esc(label)}</label>`;
 if(kind==='select')return `<label class="${className}">${caption}<select${attrs}>${options.map(o=>optionHTML(o,value)).join('')}</select>${helpHTML}</label>`;
 if(kind==='textarea')return `<label class="${className}">${caption}<textarea${attrs}${rows?` rows="${rows}"`:''}>${esc(value??'')}</textarea>${helpHTML}</label>`;
 const type=kind==='number'?'number':kind==='date'?'date':kind==='url'?'url':'text';
 let datalist='',listAttr='';
 if(type==='text'&&(list||options.length)){const id=list||nextId('field-list');listAttr=` list="${id}"`;if(!list)datalist=`<datalist id="${id}"${d.picker?` data-picker="${esc(d.picker)}"`:''}>${options.map(o=>{const x=optionOf(o);return `<option value="${esc(String(x.title??x.id))}">${x.note?esc(String(x.note)):''}</option>`;}).join('')}</datalist>`;}
 else if(type==='text'&&d.picker&&!PROJECT_PICKERS.has(d.picker)){const id=nextId('field-list');listAttr=` list="${id}"`;datalist=`<datalist id="${id}" data-picker="${esc(d.picker)}"></datalist>`;schedulePickers();}
 return `<label class="${className}">${caption}<input type="${type}"${attrs}${listAttr} value="${esc(value??'')}">${datalist}${helpHTML}</label>`;
}
// ---------------------------------------------------------------- a long list to choose from (round 12, G, GR-UX-05)
// An ids field of more than PICK_FROM options is a searchable list, not a fieldset of every checkbox (1,400 of them on an
// imported project). The chosen records stand as chips, each carrying the field's value in a hidden input, so the form
// reads them as it read the ticked boxes (FormData getAll); a disabled input keeps the field's name on the form. The
// search reads each option's id, reference, title and note and, for a requirement of the open project, the text every
// requirement search reads (requirement-groups.js requirementSearchIndex: the register's search text and the groups
// that hold it); it lists the first PICK_SHOWN matches, each a button that adds it, and says how many more there are.
// The options stay with the page (pickLists), never in the markup.
const PICK_FROM=30,PICK_SHOWN=20,pickLists=new Map();
let pickCleanupScheduled=false;
function schedulePickCleanup(){
 if(pickCleanupScheduled||typeof document==='undefined')return;
 pickCleanupScheduled=true;
 // Editors render several fields before mounting the completed HTML. Prune afterward,
 // retaining every visible control and a small tail of not-yet-mounted render results.
 // A large needs editor must not lose the handlers for its first fields.
 setTimeout(()=>{pickCleanupScheduled=false;const mounted=new Set([...document.querySelectorAll('[data-pick]')].map(el=>el.dataset.pick)),recent=new Set([...pickLists.keys()].slice(-20));for(const key of pickLists.keys())if(!mounted.has(key)&&!recent.has(key))pickLists.delete(key);},0);
}
const pickCount=list=>`${list.chosen.size.toLocaleString('en-GB')} of ${list.options.length.toLocaleString('en-GB')} chosen`;
const chipHTML=(name,x)=>`<span class="l-pick-chip">${name?`<input type="hidden" name="${esc(name)}" value="${esc(String(x.id))}">`:``}<b>${esc(String(x.strong||x.id))}</b>${x.title?` <span title="${esc(String(x.title))}">${esc(shortText(String(x.title),48))}</span>`:''}<button type="button" data-pick-remove="${esc(String(x.id))}" aria-label="Remove ${esc(String(x.strong||x.id))}" title="Remove">×</button></span>`;
function pickResultsHTML(list,query){
 const words=String(query||'').trim().toLowerCase().split(/\s+/).filter(Boolean);
 const hits=list.options.filter(x=>!x.disabled&&!list.chosen.has(String(x.id))&&words.every(w=>x.text.includes(w))),shown=hits.slice(0,PICK_SHOWN);
 return (shown.map((x,i)=>`${i===0||shown[i-1].group!==x.group?`<li class="l-pick-group">${esc(x.group)}</li>`:``}<li><button type="button" data-pick-add="${esc(String(x.id))}"><b>${esc(String(x.strong||x.id))}</b> ${esc(String(x.title??''))}${x.note?`<small>${esc(String(x.note))}</small>`:''}</button></li>`).join('')||`<li class="l-pick-none">${words.length?'Nothing else matches this search.':'Every record is chosen.'}</li>`)
  +(hits.length>shown.length?`<li class="l-pick-more">and ${(hits.length-shown.length).toLocaleString('en-GB')} more: narrow the search</li>`:'');
}
// `helpId` names the help inside helpHTML: the Find box a person types in is described by it (rc41 close).
function pickHTML(name,label,helpHTML,options,chosen,joined=false,helpId=''){
 const p=openProject(),id=nextId('pick'),reqs=Array.isArray(p?.artefacts)?requirementSearchIndex(p):null;
 const xs=options.map(o=>{const x=optionOf(o),chapter=x.chapter||chapterOfRecord(p,x.id);return {...x,group:x.group||(chapter?'Chapter '+chapter+' · '+(CHAPTER_TITLES[chapter]||''):'Other linked records'),chapter,text:[x.id,x.strong,x.title,x.note,x.search,reqs?.get(String(x.id))].filter(Boolean).join(' ').toLowerCase()};});
 const currentChapter=typeof location!=='undefined'?Number(new URLSearchParams(location.search).get('chapter')||1):0;xs.sort((a,b)=>(a.chapter===currentChapter?-1:0)-(b.chapter===currentChapter?-1:0)||(a.chapter||99)-(b.chapter||99));
 const list={name,joined,options:xs,byId:new Map(xs.map(x=>[String(x.id),x])),chosen:new Set(chosen)};
 pickLists.set(id,list);schedulePickCleanup();
 return `<fieldset class="l-checks l-pick" data-pick="${esc(id)}"><legend>${esc(label)}</legend>${helpHTML}${joined?`<input type="hidden" name="${esc(name)}" data-pick-value value="${esc(chosen.join(', '))}">`:`<input type="hidden" name="${esc(name)}" value="" disabled>`}<p class="l-pick-count" role="status">${pickCount(list)}</p><div class="l-pick-chips">${chosen.map(c=>chipHTML(joined?'':name,list.byId.get(c)||{id:c})).join('')}</div>`
  +`<label class="l-pick-find"><span>Find</span><input type="search" data-pick-find placeholder="An id, external id, domain or group" autocomplete="off" aria-label="Find ${esc(label)}"${helpId?` aria-describedby="${esc(helpId)}"`:''}></label><ul class="l-pick-results" aria-label="${esc(label)}: records to add">${pickResultsHTML(list,'')}</ul></fieldset>`;
}
if(typeof document!=='undefined'&&typeof document.addEventListener==='function'){
 document.addEventListener('input',e=>{const f=e.target?.closest?.('[data-pick-find]'),box=f?.closest('[data-pick]'),list=box&&pickLists.get(box.dataset.pick);if(list)box.querySelector('.l-pick-results').innerHTML=pickResultsHTML(list,f.value);});
 document.addEventListener('click',e=>{
  const b=e.target?.closest?.('[data-pick-add],[data-pick-remove]'),box=b?.closest('[data-pick]'),list=box&&pickLists.get(box.dataset.pick);if(!list)return;
  e.preventDefault();const add=b.hasAttribute('data-pick-add'),id=add?b.dataset.pickAdd:b.dataset.pickRemove,find=box.querySelector('[data-pick-find]');
  if(add){if(!list.chosen.has(id)){list.chosen.add(id);box.querySelector('.l-pick-chips').insertAdjacentHTML('beforeend',chipHTML(list.joined?'':list.name,list.byId.get(id)||{id}));}}
  else{list.chosen.delete(id);b.closest('.l-pick-chip')?.remove();}
  box.querySelector('.l-pick-results').innerHTML=pickResultsHTML(list,find.value);box.querySelector('.l-pick-count').textContent=pickCount(list);if(list.joined)box.querySelector('[data-pick-value]').value=[...list.chosen].join(', ');
  // The form's own listeners hear it as they heard a box ticked; focus stays with the search.
  box.dispatchEvent(new Event('change',{bubbles:true}));find.focus();
 });
}
// One field of a record type by name, with its help and its picker: the way every editor draws a field.
// `project` (or the open project store) supplies the stakeholder and assumption pickers.
export function recordField(command,name,value='',opts={}){
 const d=fieldOf(command,name);
 if(!d){if(typeof console!=='undefined')console.warn('No field descriptor for '+command+'.'+name);return fieldHTML({name,label:opts.label||name,kind:opts.kind||'text'},value,opts);}
 const o={help:fieldHelp(command,name),...opts};
 if(name==='grounds'){const p=o.project||openProject();if(p){const options=[...(p.artefacts||[]).filter(x=>x.type==='requirement').map(x=>({id:x.id,strong:x.externalId||x.id,title:x.title,chapter:1,group:'Chapter 1 · Requirements'})),...requirementGroups(p).map(x=>({id:x.id,strong:x.id,title:x.title,chapter:1,group:'Chapter 1 · Requirement groups'}))];const fieldName=o.item!=null?(d.prefix||name+':')+o.item:name;const helpId=nextId('field-help');return pickHTML(fieldName,o.label||d.label,`<p class="field-help" id="${helpId}">Choose the requirements and groups this record answers. Existing links stay selected when you search.</p>`,options,String(value||'').split(/[\s,;]+/).filter(Boolean),true,helpId);}}
 if(d.picker&&PROJECT_PICKERS.has(d.picker)&&!o.options)o.options=pickerOptions(d.picker,o.project);
 return fieldHTML(d,value,o);
}
// Several fields of one record, by name, in the order given; `opts[name]` carries that field's options or label.
export const recordFields=(command,record,names,opts={})=>names.map(n=>recordField(command,n,record?.[n],opts[n]||{})).join('');
// A renderer bound to one record type: `const f=kitFor('runtime.plan'); f('title',r.title)`.
export const kitFor=command=>(name,value,opts)=>recordField(command,name,value,opts);
// A standalone confirmation box (an acknowledgement a handoff or an intake asks for) and a page-level chooser (the
// environment a chapter shows, a list's filter), drawn by the same renderer from an inline descriptor.
export const checkHTML=(name,label,{value=false,required=false}={})=>fieldHTML({name,label,kind:'checkbox'},value,{required});
export const selectHTML=(name,label,options,value,opts={})=>fieldHTML({name,label,kind:'select'},value,{options,...opts});

// ---------------------------------------------------------------- pickers
// Those read from the open project (synchronously) and those read from the knowledge once the editor is on screen.
const PROJECT_PICKERS=new Set(['stakeholder','assumption']);
const openProject=()=>(typeof window!=='undefined'?window.aiwProjectStore?.value?.document:null)||null;
export function pickerOptions(picker,project=openProject()){
 const artefacts=Array.isArray(project?.artefacts)?project.artefacts:[];
 if(picker==='stakeholder')return artefacts.filter(a=>a.type==='stakeholder'||a.type==='actor').map(a=>({id:a.id,title:a.title,note:a.id}));
 if(picker==='assumption')return artefacts.filter(a=>a.type==='assumption').map(a=>({id:a.id,strong:a.id,title:a.title,note:a.confirmed?'Confirmed':'Unconfirmed'}));
 return [];
}
// The catalogue's styles and patterns, its anti-patterns, and the playbook's tactics, as datalist rows, loaded once
// and only when an editor shows such a field.
let knowledge=null,scheduled=false;
async function loadKnowledge(){
 if(knowledge)return knowledge;
 const {BRAIN_CATALOGUE}=await import('./brain-catalogue.js');
 const records=Array.isArray(BRAIN_CATALOGUE?.records)?BRAIN_CATALOGUE.records:[];
 const rows=kinds=>records.filter(r=>kinds.includes(r.recordType)).map(r=>({title:r.name,note:r.recordType==='style'?'Style':r.recordType==='anti-pattern'?'Anti-pattern':'Pattern'}));
 knowledge={'pattern':rows(['style','pattern']),'anti-pattern':rows(['anti-pattern']),'tactic':(Array.isArray(TACTICS)?TACTICS:[]).map(t=>({title:t.name,note:t.attribute?t.attribute+' · '+t.group:t.group||''}))};
 return knowledge;
}
export async function fillPickers(root=typeof document!=='undefined'?document:null){
 if(!root?.querySelectorAll)return 0;
 const lists=[...root.querySelectorAll('datalist[data-picker]:empty')];if(!lists.length)return 0;
 const k=await loadKnowledge();let filled=0;
 for(const l of lists){const rows=k[l.dataset.picker]||[];if(!rows.length||!l.isConnected)continue;l.innerHTML=rows.map(o=>`<option value="${esc(String(o.title))}">${esc(String(o.note||''))}</option>`).join('');filled++;}
 return filled;
}
function schedulePickers(){if(scheduled||typeof document==='undefined')return;scheduled=true;setTimeout(()=>{scheduled=false;fillPickers().catch(e=>console.warn('The knowledge pickers could not load.',e?.message));},0);}
